    # Right and left borders, interior rows
    for c in [c1, c2]:
        for r in range(r1 + 1, r2):
            grid[r][c] = '1'

    # Interior fill with checkerboard 6/0 (local_r + local_c % 2 == 0)
    # Interior: rows 2-5, cols 4-10
